-- Barra Noctalia transparente: sin blur detrás (el fondo lo da el wallpaper)
hl.layer_rule({
    name  = "noctalia-bar-crisp-gaps",
    match = { namespace = "^noctalia-bar-default$" },
    blur = false,
    ignore_alpha = 0.0,
})
hl.layer_rule({
    name  = "noctalia-panels-no-blur",
    match = { namespace = "^noctalia-(attached-panel|panel|notification|osd|window-switcher)$" },
    blur = true,
    ignore_alpha = 1.0,
})

-- Noctalia Settings: ventana flotante centrada
hl.window_rule({
    name = "noctalia-settings",
    match = { class = "dev.noctalia.Noctalia" },
    float = true,
    size = { 1080, 920 },
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Plus: diálogos y utilidades flotantes centradas (no tapan el tiling)
for _, cls in ipairs({
    "org.gnome.NautilusPreviewer",
    "org.gnome.FileRoller",
    "org.gnome.Loupe",
    "org.gnome.Calculator",
    "pavucontrol",
    "blueman-manager",
    "nm-connection-editor",
    "xdg-desktop-portal-gtk",
    "hyprpolkitagent",
}) do
    hl.window_rule({
        name  = "float-" .. cls,
        match = { class = cls },
        float = true,
        center = true,
        size = { 1200, 800 },
    })
end
-- Nautilus principal: flotante grande centrado (SUPER+E)
hl.window_rule({
    name  = "float-nautilus",
    match = { class = "org.gnome.Nautilus" },
    float = true,
    center = true,
    size = { 1500, 900 },
})
-- Steam / diálogos pequeños
hl.window_rule({
    name  = "float-dialogs",
    match = { title = "^(Open|Save|Save As|Choose|Select).*$" },
    float = true,
    center = true,
})

-- Kitty: sin decoración en Hyprland (en GNOME la pone kitty.conf)
hl.window_rule({
    name  = "kitty-no-decor",
    match = { class = "^(kitty|Kitty)$" },
    decorate = false,
})

-- Zen: mantener transparencia real (alpha) también en inactivo
-- No bajar opacity: el mod TransparentZen usa alpha por píxel, no opacity global.
-- El gris al perder foco lo pone Zen (zen.view.grey-out-inactive-windows), ver about:config.
hl.window_rule({
    name = "zen-keep-transparency",
    match = { class = "(app.zen_browser.zen|Zen-Personal)" },
    opacity = "1.0 override 1.0 override",
    opaque = false,
    no_blur = false,
})

-- For Noctalia Color templates
